import{_ as a,o as s,c as t,l as r,t as o,N as n}from"./chunks/framework.Gjrf2Eoj.js";const _=JSON.parse('{"title":"group | x-cmd man (man5) | user group file","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | group - user group file","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"group | x-cmd man (man5) | user group file"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | group - user group file"}]]},"headers":[],"params":{"isMan":true,"man":"group","category":"man5","desc":"user group file"},"relativePath":"man5/group.md","filePath":"man5/group.md"}'),i={name:"man5/group.md"},d={class:"visually-hidden"},p=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>group - user group file</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <em>/etc/group</em> file is a text file that defines the groups on the system. There is one entry per line, with the following format:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">group_name:password:GID:user_list</span></span></code></pre></div><p>The fields are as follows:</p><dl><dt><em>group_name</em></dt><dd>the name of the group.</dd><dt><em>password</em></dt><dd>the (encrypted) group password. If this field is empty, no password is needed.</dd><dt><em>GID</em></dt><dd>the numeric group ID.</dd><dt><em>user_list</em></dt><dd>a list of the usernames that are members of this group, separated by commas.</dd></dl><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p><em>/etc/group</em></p><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>As the 4.2BSD <strong>initgroups</strong>(3) man page says: no one seems to keep <em>/etc/group</em> up-to-date.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>chgrp</strong>(1), <strong>gpasswd</strong>(1), <strong>groups</strong>(1), <strong>login</strong>(1), <strong>newgrp</strong>(1), <strong>sg</strong>(1), <strong>getgrent</strong>(3), <strong>getgrnam</strong>(3), <strong>gshadow</strong>(5), <strong>passwd</strong>(5), <strong>vigr</strong>(8)</p>',13);function g(e,l,m,h,u,c){return s(),t("div",null,[r("h1",d,o(e.$params.man),1),p])}const b=a(i,[["render",g]]);export{_ as __pageData,b as default};
